

# =====================================================================
# THE CELLS OF CHAPTER 17 — F1 the blemished sacrifice, F2 the idolater's trial, F3 the high court, F4 the king (each ask a case; the verdicts DATA rows or PARAMETERS)
# =====================================================================
def the_blemished_sacrifice(case, data):
    """F1 — Deut 17:1 — THE LINE blemished_sacrifice_barred writing blemished_offering_barred (a BLOCK); the south a dispute, the classes parameters; 15:21's and Leviticus 22's classes by CALL (release_firstborn, priesthood); the three true prohibitions by CALL (place_name)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_south_and_the_blemish':
        ink('17:1', '"YOU SHALL NOT SACRIFICE TO THE LORD YOUR GOD AN OX OR A SHEEP WHICH HAS A BLEMISH, ANY EVIL THING" — the negation %s; "blemish" in the two chapters %s; 15:21 the closest kin %s' % (NEG[(17, 1)], [(c, v) for (c, v) in SPAN if 'מום' in W(c, v)], KINC[(17, 1)][0]))
        move('the Sifrei 147:1 (read whole at the reading)', "R. JUDAH: might one who slaughters a sin offering in the south transgress a prohibition? 'which has a blemish' — for the blemish he transgresses, not for the south; THE SAGES: even for the south — TWO ARMS on the spine's own row, both recorded")
        dat("THE PARAMETER the_south_and_the_blemish (two arms: R. Judah the blemish alone / the sages even the south); the exam's person the slaughterer of a sin offering in the south — barred from it by the sages' arm, exempt by R. Judah's")
        return out("the south and the blemish (17:1) — the blemish transgresses (R. Judah), even the south (the sages): the Sifrei 147:1, two arms a DATA row; THE WRITE blemished_offering_barred, a BLOCK on Israel at the chapters' own day; the slaughterer in the south barred from it by the sages' arm", ['blemished_offering_barred'])
    if ask == 'the_three_true_prohibitions':
        ink('17:1', '"you shall not sacrifice" with 12:17\'s "you may not eat within your gates" and 16:5\'s "you may not sacrifice the Passover" — the three seats the spine names; holy_things_in_the_gates_barred on Israel %s' % (PN_GATES[1],))
        move('the Sifrei 147:2 (reread whole — read before at chapters 12 and 16); cold_run_place_name (CALL) — PN.you_may_not_eat_within_your_gates = %s' % (PN_GATES[0][:60],), "MIGHT ONE WHO PUTS OFFERINGS BEFORE ONE ANOTHER TRANSGRESS? the teaching says 12:17, 16:5, 17:1 — THE THREE TRUE PROHIBITIONS of the place; the order of offerings no prohibition (Mishnah Zevachim 10:1 the order's answer sheet — owed)")
        dat("the three true prohibitions a DATA row (12:17, 16:5, 17:1 — place_name's block and festivals_judges' the tape's lines); the exam's person the one who offers the additional before the daily — accepted (no prohibition, the order alone)")
        return out("the three true prohibitions (17:1) — 12:17's gates, 16:5's Passover, 17:1's blemish (the Sifrei 147:2; place_name by CALL: %s): the one who puts the additional before the daily accepted — the order no prohibition" % (PN_GATES[1][0],), ['accepted'])
    if ask == 'born_blemished_and_any_evil_thing':
        ink('17:1', '"WHICH HAS A BLEMISH, ANY EVIL THING" — the phrase %s; 15:21\'s "any blemish, lame or blind, any ill blemish" the twin (shared %d)' % (W(17, 1)[7:12], TWIN['17:1 vs 15:21']))
        move('the Sifrei 147:3-4 (reread whole — read before at chapter 15); cold_run_release_firstborn (CALL) — RF.the_blemish_class = %s; cold_run_priesthood (CALL) — PR.acceptable(class_sweep) = %s, (passing_blemish) = %s' % (RF_CLASS[1], PR_SWEEP[:3], PR_PASS), "ONLY ONE BORN WHOLE AND MADE BLEMISHED? one born blemished from its mother's womb — 'any evil thing'; the scabbed, the warted, the lichened — 'a blemish, any evil thing'; the old, the sick, the foul — 'an ox or a sheep … any evil thing' (147:3-4): the classes WIDENED by the clause, 15:21's particulars teaching the class (Bekhorot 37a — the firstling's cell by CALL), Leviticus 22's sweep by CALL")
        dat("THE PARAMETER the_blemish_classes (born blemished; the scabbed, the warted, the lichened; the old, the sick, the foul — from the verse's three clauses); the exam's person the one who offers a beast born blemished — barred from it")
        return out("born blemished and any evil thing (17:1) — the born-blemished, the scabbed and the old widened in by the clause (the Sifrei 147:3-4; release_firstborn's class %s and priesthood's sweep by CALL): the one who offers a beast born blemished barred from it" % (RF_CLASS[1][0],), ['barred_from_it'])
    if ask == 'outside_its_time_and_place':
        ink('17:1', '"ANY EVIL THING" — "thing" %s the word the row reads; the intention-disqualified offering' % ([x for x in W(17, 1) if x == 'דבר'],))
        move('the Sifrei 147:5 (read whole at the reading)', "WHENCE THAT OFFERINGS SLAUGHTERED OUTSIDE THEIR TIME OR PLACE TRANSGRESS A PROHIBITION? 'thing' — what depends on a thing (a word, the intention): the piggul and the notar under this verse's prohibition (Mishnah Zevachim 2:2-3 the answer sheet — owed)")
        dat("outside its time and place a DATA row (the intention-disqualified offering under 17:1's prohibition); the exam's person the slaughterer who intends to eat outside the time — barred from it")
        return out("outside its time and place (17:1) — 'thing': what depends on a word, the intention-disqualified offering a prohibition here (the Sifrei 147:5): the slaughterer who intends outside the time barred from it", ['barred_from_it'])
    if ask == 'the_mounter_and_the_harlots_hire':
        ink('17:1', '"FOR IT IS AN ABOMINATION TO THE LORD YOUR GOD" — "abomination" in the two chapters %s; 14:3 and 23:19 the shared word (99:2, 261:2 the outside rows)' % ([(c, v) for (c, v) in SPAN if any('תועב' in x for x in W(c, v))],))
        move('the Sifrei 147:6 (read whole at the reading); 99:2, 261:2 (the outside rows — the analogy by the shared word); cold_run_seven_nations (CALL) — SN.abomination_to_the_lord = %s' % (SN_ABOM[1],), "WHENCE THE MOUNTER AND THE MOUNTED, THE SET-ASIDE AND THE WORSHIPPED? 'it is an abomination to the LORD your God'; whence the harlot's hire, the dog's price, the mixed, the torn, the caesarean? 'for it is an abomination'; R. JUDAH: it is an abomination, its offspring is not (147:6 — Mishnah Temurah 6:1-3 the answer sheet, owed)")
        dat("the mounter and the harlot's hire a DATA row (the nine disqualified by 'abomination'; the offspring permitted by R. Judah); the exam's person the one who offers the dog's price — barred from it")
        return out("the mounter and the harlot's hire (17:1) — nine disqualified by 'abomination' (the Sifrei 147:6; 14:3 and 23:19 the shared word — 99:2, 261:2), the offspring not (R. Judah): the one who offers the dog's price barred from it", ['barred_from_it'])
    if ask == 'the_sacrifice_not_the_sacrificer':
        ink('17:1', '"IT" — the pronoun %s the row reads; the sacrifice, not the sacrificer' % ([x for x in W(17, 1) if x == 'הוא'],))
        move('the Sifrei 147:7 (read whole at the reading)', "R. SIMEON: since the mounter and the mounted are disqualified among beasts, might the man be too? the teaching says 'it' — OF THE SACRIFICE I SPOKE, NOT OF THE SACRIFICER: the offerer's own disqualifications are not this verse's")
        dat("the sacrifice not the sacrificer a DATA row (the pronoun limits the bar to the animal); the exam's person the transgressor who brings a whole beast — accepted (his offering not this verse's abomination)")
        return out("the sacrifice, not the sacrificer (17:1) — 'it' limits the abomination to the animal (the Sifrei 147:7): the transgressor who brings a whole beast accepted under this verse", ['accepted'])
    return 'no verdict in span', [], list(P_)


def the_idolaters_trial(case, data):
    """F2 — Deut 17:2-7 — THE LINE idolater_trial_declared writing idolater_inquiry_required, two_witnesses_required, witnesses_hand_first_commanded (STATUSES) and one_witness_barred (a BLOCK); chapter 13's cells by CALL (seducers), the one witness by CALL (refuge, ordinances), the stones by CALL (mekoshesh); the idolater's own verdict stoned and purged (the body effects reused)"""
    del P_[:]
    ask = case['ask']
    if ask == 'found_means_witnesses':
        ink('17:2', '"WHEN THERE IS FOUND in your midst, in one of your gates" — "found" %s; the parser [1] %s; 19:15 the closest kin of 17:6 %s' % ([x for x in W(17, 2) if x == 'ימצא'], PARSE[(17, 2)][0], KINC[(17, 6)][0]))
        move('the Sifrei 148:1 (read whole at the reading); cold_run_refuge (CALL) — RG.DATA[the_one_witness] = %s' % (RG_ONE['value'],), "'WHEN THERE IS FOUND' — BY WITNESSES; from 19:15's 'by the mouth of two witnesses or three shall a matter stand' a building from a father: wherever 'found' is said, two or three witnesses (148:1 — the verse AHEAD cited by the spine; refuge's bare plural two by the prototype)")
        dat("found means witnesses a DATA row (the passive verb the witnesses' finding; 19:15's building from a father — its own compile owed to chapter 19); the exam's person the idolater found by one witness — exempt (not 'found')")
        return out("found means witnesses (17:2) — 'when there is found' by two or three witnesses, 19:15's building from a father (the Sifrei 148:1; refuge's %s by CALL): the idolater found by one witness exempt" % (RG_ONE['value'],), ['exempt'])
    if ask == 'the_gate_and_the_stoning':
        ink('17:2, 17:5', '"in one of your gates" and "bring them out to your gates" — "your gates" at %s; "stone them with stones" %s; 13:16\'s sword the seducers\' kin' % ([(c, v) for (c, v) in SPAN if 'שעריך' in W(c, v)], [x for x in W(17, 5) if x.startswith('וסקלתם')]))
        move('the Sifrei 148:2-4, 149:3-4 (read whole at the reading); cold_run_seducers (CALL) — SE.the_sword = %s' % (SE_SWORD[1],), "THE GATE WHERE THEY WERE FOUND, NOT WHERE THEY WERE JUDGED — 'your gates' 'your gates' an analogy by the shared word, read both ways (148:2, 149:4); the led-astray die by the sword, the seducers by stoning (148:3 — 'stone them'); a city is not made a city led astray by one witness nor by a woman, but the single seducer is liable (148:4); 'in Israel' widened to sojourners, women and slaves by 'the man or the woman' (149:3)")
        dat("THE PARAMETER the_gate (the gate where found, not where judged); the exam's person the idolater found in one city and judged in another — stoned at the gate where found")
        return out("the gate and the stoning (17:2, 17:5) — the gate where found, not where judged; the seducers stoned where the led-astray fall by the sword (the Sifrei 148:2-4, 149:3-4; seducers' sword %s by CALL): the idolater stoned at the gate where found, the evil purged" % (SE_SWORD[1][0],), ['stoned', 'evil_purged_from_the_midst'])
    if ask == 'the_three_acts_and_the_associator':
        ink('17:3', '"and goes and serves other gods and bows to them, to the sun or the moon or all the host of heaven, WHICH I HAVE NOT COMMANDED" — the three verbs %s; 4:19\'s host the kin (obey_horeb)' % ([x for x in W(17, 3) if x in ('וילך', 'ויעבד', 'וישתחו')],))
        move('the Sifrei 148:6-8 (read whole at the reading; 148:8 reread from chapter 4); cold_run_covenant_at_horeb (CALL) — CH.bow_and_serve = %s; cold_run_obey_horeb (CALL) — OH.DATA[the_host_apportioned] = %s' % (CH_BOW[1], OH_HOST['value']), "ONLY THIS ONE? the server — 'and goes and serves other gods'; the bower — 'and bows to them' (148:6: the three acts each liable); 'to serve them' (28:14) — to include THE ASSOCIATOR who joins the Name with another's (148:7 — the verse ahead cited); R. Yose the Galilean: 4:19's 'apportioned to all the peoples' against 29:25's 'not apportioned' (148:8 — the pair the obey_horeb row carries): the host not given to the nations to worship")
        dat("the three acts and the associator a DATA row (the goer, the server, the bower; the associator by 28:14; the host not apportioned); the exam's person the one who bows to the sun — put to death by the second word's answer sheet (covenant_at_horeb by CALL)")
        return out("the three acts and the associator (17:3) — the goer, the server, the bower each liable; the associator by 28:14; the host not apportioned (the Sifrei 148:6-8; covenant_at_horeb's bow-and-serve %s and obey_horeb's host by CALL): the one who bows to the sun put to death" % (CH_BOW[1][0],), ['put_to_death'])
    if ask == 'the_seven_investigations':
        ink('17:4', '"and it is told you AND YOU HEAR AND INQUIRE WELL, and behold it is true, the thing certain" — 17:4 shares %d of its tokens in order with 13:15 %s (the reading\'s assert)' % (TWIN['17:4 vs 13:15'], SHARED(DV(17, 4), DV(13, 15))))
        move('the Sifrei 149:1-2, 93:6, 190:7 (read whole — the analogy at three verses); cold_run_seducers (CALL) — SE.the_seven_interrogations = %s, SE.the_congruence_rule = %s' % (SE_SEVEN[1], SE_CONGR[1]), "'WELL' 'WELL' AN ANALOGY with 13:15's 'inquire, search, ask well': THEY EXAMINE HIM WITH SEVEN INVESTIGATIONS; probes from 'and behold it is true'; investigations — 'I do not know' voids the testimony, probes — it stands; in both a contradiction voids (149:1-2 — Mishnah Sanhedrin 5:1-2 by the seducers' cell): ONE QUESTIONNAIRE for the city, the idolater and the conspiring witnesses (93:6, 149:1, 190:7)")
        dat("THE WRITE idolater_inquiry_required — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_seven_investigations (the cycle, the year, the month, the day, the weekday, the hour, the place); the exam's person the witness who says 'I do not know' at an investigation — accepted against, the testimony void")
        return out("the seven investigations (17:4) — 'well' 'well' the analogy with 13:15 at three verses: the seven investigations, the probes, the contradiction rule (the Sifrei 149:1-2, 93:6, 190:7; seducers' %s by CALL): THE WRITE idolater_inquiry_required, a STATUS on Israel at the chapters' own day; the witness who says 'I do not know' at an investigation accepted against" % (SE_SEVEN[1][0],), ['idolater_inquiry_required'])
    if ask == 'the_three_exclusions':
        ink('17:5', '"bring out THAT MAN or THAT WOMAN" — the pronoun %s twice; 155:8 the same three on the rebel' % ([x for x in W(17, 5) if x in ('ההוא', 'ההיא')],))
        move('the Sifrei 149:5-6 (read whole at the reading)', "'THAT MAN' — not the coerced, not the unwitting, not the misled; 'THAT WOMAN' — not the coerced, the unwitting, the misled (fem.): THREE EXCLUSIONS from each pronoun — the liability conditions (intent, knowledge, freedom); 155:8 carries the same three to the rebel elder")
        dat("THE PARAMETER the_three_exclusions (the coerced, the unwitting, the misled — from the pronoun, for the man and for the woman); the exam's person the one who served under coercion — exempt")
        return out("the three exclusions (17:5) — the coerced, the unwitting, the misled excluded by 'that man' and 'that woman' (the Sifrei 149:5-6; 155:8 the same on the rebel): the one who served under coercion exempt", ['exempt'])
    if ask == 'two_witnesses_for_every_death':
        ink('17:6', '"BY THE MOUTH OF TWO WITNESSES OR THREE WITNESSES SHALL THE DEAD DIE" — the parser %s; 19:15 the closest kin %s; 190:3 the outside row — men, not women' % (PARSE[(17, 6)][0], KINC[(17, 6)][0]))
        move('the Sifrei 150:1, 190:3 (read whole at the reading); cold_run_refuge (CALL) — the prototype %s; cold_run_ordinances (CALL) — OR.courts(circumstantial) = %s' % (RG_ONE['settings']['the_prototype'][:70], OR_CIRC), "ONLY THIS ONE? WHENCE ALL THE OTHERS PUT TO DEATH? the teaching says the verse again — 'shall the dead die': TWO WITNESSES FOR EVERY CAPITAL CASE (150:1); 'two' 'two' with 19:15: as there men and not women, so here (190:3); no execution without witnesses (the Mekhilta — ordinances by CALL)")
        dat("THE WRITE two_witnesses_required — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_witnesses_number (two or three, men); the exam's person the court that executes on one witness's testimony and circumstance — barred from it")
        return out("two witnesses for every death (17:6) — 'shall the dead die' every capital case, men not women (the Sifrei 150:1, 190:3; refuge's %s and ordinances' %s by CALL): THE WRITE two_witnesses_required, a STATUS on Israel at the chapters' own day; the court that executes on one witness barred from it" % (RG_ONE['value'], OR_CIRC), ['two_witnesses_required'])
    if ask == 'one_witness_and_the_disciple_silent':
        ink('17:6', '"HE SHALL NOT DIE BY THE MOUTH OF ONE WITNESS" — the negation %s; "one" the parser\'s third number %s' % (NEG[(17, 6)], PARSE[(17, 6)][0][2]))
        move('the Sifrei 150:2-3 (read whole at the reading); cold_run_ordinances (CALL) — OR.courts(one_vs_two) = %s, (no_retrial_acquitted) = %s' % (OR_ONE_TWO, OR_NORETRIAL), "WHENCE THAT ONE WITNESS DOES NOT ARGUE FOR GUILT? 'he shall not die by the mouth of one witness'; WHENCE THAT A DISCIPLE DOES NOT ARGUE FOR GUILT? the same clause (150:2-3 — the single witness and the disciple silent for the prosecution, Sanhedrin 5:4 by the English's note); acquit by one and convict by two, reversed for merit not for liability (Mishnah Sanhedrin 4:1 — ordinances by CALL)")
        dat("THE WRITE one_witness_barred — a BLOCK on israel_people at the chapters' own day (DI2); the exam's person the disciple who argues for guilt — barred from it; the single witness the same")
        return out("one witness and the disciple silent (17:6) — neither argues for guilt (the Sifrei 150:2-3; ordinances' %s by CALL): THE WRITE one_witness_barred, a BLOCK on Israel at the chapters' own day; the disciple who argues for guilt barred from it" % (OR_ONE_TWO,), ['one_witness_barred'])
    if ask == 'the_witnesses_hand_first':
        ink('17:7', '"THE HAND OF THE WITNESSES SHALL BE ON HIM FIRST to put him to death, and the hand of all the people afterward; and you shall purge the evil from your midst" — 17:7 shares %d tokens in order with 13:10 %s; the purge formula\'s second seat of nine' % (TWIN['17:7 vs 13:10'], SHARED(DV(17, 7), DV(13, 10))))
        move('the Sifrei 149:7, 151:1-3, 306:9 (read whole at the reading); cold_run_seducers (CALL) — SE.the_hand_first = %s, SE.the_purge_formulas_nine_seats = %s; cold_run_mekoshesh (CALL) — MK.stones_and_a_stone = %s' % (SE_HAND[1], SE_NINE[:40], MK_STONES[0]), "A COMMANDMENT ON THE WITNESSES TO PUT HIM TO DEATH (151:1); if he did not die by the witnesses' hand he dies by any man's (151:2 — Sanhedrin 6:4, R. Benaiah's image at 306:9); 'stone them with stones' — many? Leviticus 20:27's 'with a stone'; one? here 'stones': if not by the first, by the second (149:7 — mekoshesh's cell: the second witness's stone, all Israel's stones); 'purge the evil from your midst' — PURGE THE DOERS OF EVIL FROM ISRAEL (151:3 — persons, not an abstraction; Onkelos 'the doer of evil'; the formula's second seat of nine)")
        dat("THE WRITE witnesses_hand_first_commanded — a STATUS on israel_people at the chapters' own day (DI2); the exam's person the idolater convicted on two witnesses — stoned by the witnesses' hand first and the evil purged (chapter 13's body effects reused, never a line's write)")
        return out("the witnesses' hand first (17:7) — the witnesses execute, any man after, the second stone (the Sifrei 151:1-2, 149:7; seducers' hand-first %s and mekoshesh's %s by CALL), the doers of evil purged (151:3 — the formula's second seat): THE WRITE witnesses_hand_first_commanded, a STATUS on Israel at the chapters' own day; the convicted idolater stoned and the evil purged" % (SE_HAND[1][0], MK_STONES[0][:24]), ['witnesses_hand_first_commanded', 'stoned', 'evil_purged_from_the_midst'])
    return 'no verdict in span', [], list(P_)


def the_high_court(case, data):
    """F3 — Deut 17:8-13 — THE COURTS' SECOND DAEMON'S CELL — THE LINE high_court_declared writing high_court_at_the_place_commanded, sentence_binding_commanded (STATUSES) and turning_from_the_word_barred (a BLOCK); the three courts Mishnah Sanhedrin 11:2 the exam row; the tiers by CALL (festivals_judges), the sizes by CALL (exodus_story, ordinances), the hard matter by CALL (opening_speech), the place by CALL (place_name); the rebel's own verdict put_to_death"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_distinguished_judge_and_the_three_grades':
        ink('17:8', '"WHEN A MATTER IS TOO HARD FOR YOU IN JUDGMENT" — "too hard" %s (the root of wonder); 1:17\'s "the matter too hard for you" the twin (shared %d)' % ([x for x in W(17, 8) if x == 'יפלא'], TWIN['17:8 vs 1:17']))
        move('the Sifrei 152:1-4 (read whole at the reading); cold_run_opening_speech (CALL) — OP.the_hard_matter = %s' % (OP_HARD[:60],), "'TOO HARD' — THE VERSE SPEAKS OF THE DISTINGUISHED ONE (the court's distinguished judge, 152:1); 'from you' — this is counsel; 'a matter' — this is the law; 'for judgment' — this is the verdict (152:2-4): counsel, law, verdict THE THREE GRADES of the question the high court takes; 1:17's hard matter brought to Moses by CALL")
        dat("THE PARAMETER the_three_grades (counsel, the law, the verdict — the question's three kinds); the exam's person the local court's distinguished judge who cannot decide — accepted, the matter goes up")
        return out("the distinguished judge and the three grades (17:8) — 'too hard' the court's distinguished one; counsel, law, verdict (the Sifrei 152:1-4; opening_speech's hard matter by CALL): the local judge who cannot decide accepted, the matter goes up", ['accepted'])
    if ask == 'the_pairs':
        ink('17:8', '"between blood and blood, between plea and plea, between stroke and stroke, matters of contention in your gates" — the three pairs %s; Exodus 18:22\'s "every great matter" the kin (shared %d)' % ([x for x in W(17, 8) if x in ('דם', 'לדם', 'דין', 'לדין', 'נגע', 'לנגע')], SHN(DV(17, 8), ('Exod', 18, 22))))
        move('the Sifrei 152:5-10 (read whole at the reading); cold_run_exodus_story (CALL) — ES.jethro(sanhedrin_sizes) = %s; cold_run_ordinances (CALL) — OR.courts(twenty_three) = %s' % (ES_SIZES, OR_23), "BLOOD AND BLOOD — the blood of menstruation, of childbirth, of discharge; PLEA AND PLEA — money cases, capital cases, cases of lashes (the courts of three, twenty-three, twenty-three — Sanhedrin 1's sizes by CALL); STROKE AND STROKE — the plagues of men, of garments, of houses; 'MATTERS OF' — valuations, devotions, consecrations; 'CONTENTION' — the sotah's draught, the heifer's neck, the leper's cleansing; 'IN YOUR GATES' — gleaning, the forgotten sheaf, the corner (152:5-10): THE HIGH COURT'S BUSINESS enumerated from the verse's own words")
        dat("THE PARAMETER the_high_courts_business (the three bloods, the three judgments, the three plagues, the valuations, the three rites, the poor man's gifts); the exam's person the court of twenty-three that cannot decide a capital case — accepted, it goes up")
        return out("the pairs (17:8) — the bloods, the judgments, the plagues, the valuations, the rites, the gifts (the Sifrei 152:5-10; the sizes %s and the twenty-three by CALL): the court of twenty-three that cannot decide accepted, the matter goes up" % (ES_SIZES,), ['accepted'])
    if ask == 'rise_at_once_in_court':
        ink('17:8', '"AND YOU SHALL RISE AND GO UP TO THE PLACE" — "rise" and "go up" %s; the place formula\'s seat (place_name)' % ([x for x in W(17, 8) if x in ('וקמת', 'ועלית')],))
        move('the Sifrei 152:11-12, 152:15, 37:16, 317:2, 352:9 (read whole at the reading — the three outside rows on the height); cold_run_place_name (CALL) — PN.the_place_which_the_lord_will_choose = %s' % (PN_PLACE[1],), "'AND YOU SHALL RISE' — AT ONCE (152:11); 'AND YOU SHALL RISE' — IN COURT (152:12 — the referral a court's act, not a litigant's); 'AND GO UP' — the land of Israel higher than all lands and the Temple higher than all the land (152:15; 37:16, 317:2, 352:9 the same reading from three seats)")
        dat("rise at once in court a DATA row (the referral immediate, from the local court, upward to the place); the exam's person the litigant who goes up on his own — accepted against, the court refers")
        return out("rise at once, in court, up (17:8) — the referral immediate and the court's, the ascent the land's height (the Sifrei 152:11-12, 152:15; the place %s by CALL): the litigant who goes up on his own accepted against" % (PN_PLACE[1][0],), ['accepted'])
    if ask == 'the_three_courts':
        ink('17:8-10', '"to the place which the LORD your God will choose … from that place" — the place formula twice %s; "the priests the Levites" at %s' % ([(c, v) for (c, v) in SPAN if 'המקום' in W(c, v)], [(c, v) for (c, v) in SPAN if 'הלוים' in W(c, v)]))
        move('the Sifrei 152:13-14 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH SANHEDRIN 11:2 (read whole at the design — THE EXAM ROW); cold_run_festivals_judges (CALL) — FJ.the_three_tiers = %s' % (FJ_TIERS[1],), "THREE COURTS WERE THERE — at the entrance of the Temple Mount, at the entrance of the courtyard, in the Chamber of Hewn Stone; they come to the first and he says 'THUS I EXPOUNDED AND THUS MY FELLOWS, THUS I TAUGHT AND THUS MY FELLOWS'; if they have heard, they tell them; if not, to the second; if not, both come to the great court in the Chamber of Hewn Stone, FROM WHICH TORAH GOES OUT TO ALL ISRAEL (152:13-14 = Sanhedrin 11:2); the elder who returned and taught as before exempt, who instructed to act liable, the student exempt (the Mishnah's own continuation): THE COURTS' SECOND DAEMON — 16:18's three tiers (by CALL) now seated")
        dat("THE WRITE high_court_at_the_place_commanded — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_three_courts (Mishnah Sanhedrin 11:2 — the three seats and the formula); the exam's person the elder who taught his ruling but did not instruct to act — exempt")
        return out("the three courts (17:8-10) — the Temple Mount's, the courtyard's, the Chamber of Hewn Stone, the formula at each, Torah going out from the great court (the Sifrei 152:13-14 = Mishnah Sanhedrin 11:2 — the exam row read whole; festivals_judges' tiers %s by CALL): THE WRITE high_court_at_the_place_commanded, a STATUS on Israel at the chapters' own day; the elder who taught but did not instruct to act exempt" % (FJ_TIERS[1][0],), ['high_court_at_the_place_commanded'])
    if ask == 'the_court_at_yavneh_and_the_priests':
        ink('17:9-10', '"AND YOU SHALL COME to the priests the Levites and to the judge" — "come" %s; "and to the judge" %s' % ([x for x in W(17, 9) if x == 'ובאת'], [x for x in W(17, 9) if x == 'השפט']))
        move('the Sifrei 153:1-3, 154:1 (read whole at the reading)', "'AND YOU SHALL COME' — TO INCLUDE THE COURT AT YAVNEH (153:1 — the high court not bound to the place); 'to the priests the Levites' — a commandment that the court have priests and Levites in it; might it be invalid without them? 'and to the judge' — even without them it is valid (153:2-3 — a duty, not a condition); for the ruling of the great court in Jerusalem they are liable to death, not for Yavneh's (154:1)")
        dat("THE PARAMETER the_courts_composition (priests and Levites a duty, not a condition of validity; Yavneh included, its death penalty withheld); the exam's person the court without priests that rules — accepted, its ruling valid")
        return out("the court at Yavneh and the priests (17:9-10) — Yavneh included by 'come', its death withheld; the priests a duty not a condition (the Sifrei 153:1-3, 154:1): the court without priests accepted, its ruling valid", ['accepted'])
    if ask == 'the_judge_of_those_days':
        ink('17:9', '"and to the judge WHO SHALL BE IN THOSE DAYS; and you shall inquire and they shall tell you the word of judgment" — "in those days" %s' % ([x for x in W(17, 9) if x in ('בימים', 'ההם')],))
        move('the Sifrei 153:4-5 (read whole at the reading)', "R. YOSE THE GALILEAN: would you go to a judge not in your days? rather, a judge fit and established in those days; was a kinsman and became distant — fit; Ecclesiastes 7:10 'say not the former days were better' (153:4); 'the word of judgment' — these are the details of judgment (153:5 — the answer's form)")
        dat("the judge of those days a DATA row (the fit judge of one's own days; the details of judgment the answer); the exam's person the litigant who refuses his generation's judge for the former days' — accepted against")
        return out("the judge of those days (17:9) — a judge fit and established in your days, the details of judgment his answer (the Sifrei 153:4-5): the litigant who refuses his generation's judge accepted against", ['accepted'])
    if ask == 'do_and_turn_not_right_or_left':
        ink('17:10-11', '"AND YOU SHALL DO according to the word … according to the law they teach you … YOU SHALL NOT TURN from the word they tell you RIGHT OR LEFT" — the negation %s; "right or left" spelled two ways in one chapter (17:11 %s, 17:20 %s — the reading\'s assert)' % (NEG[(17, 11)], [x for x in W(17, 11) if x in ('ימין', 'ושמאל')], [x for x in W(17, 20) if x in ('ימין', 'ושמאול')]))
        move('the Sifrei 154:2-5 (read whole at the reading); cold_run_obey_horeb (CALL) — OH.DATA[the_law_bal_tosif][the_elder] = %s' % (OH_TOSIF['settings']['the_elder'][:60],), "'according to the law they teach you' — for words of Torah they are liable to death, not for words of the scribes (154:2); 'you shall do' — a positive commandment; 'you shall not turn' — a negative commandment (154:3-4: the pair on one act); 'RIGHT OR LEFT' — EVEN IF THEY SHOW YOU THAT RIGHT IS LEFT AND LEFT IS RIGHT, OBEY THEM (154:5); the rebellious elder liable only where the addition spoils (4:2's sealing — obey_horeb's row by CALL)")
        dat("THE WRITES sentence_binding_commanded (a STATUS) and turning_from_the_word_barred (a BLOCK) — on israel_people at the chapters' own day (DI2); the exam's person the one who follows the court's ruling against his own eyes — accepted")
        return out("do and turn not right or left (17:10-11) — the command and the prohibition on one act, right that is left, Torah not the scribes (the Sifrei 154:2-5; obey_horeb's sealing by CALL): THE WRITES sentence_binding_commanded and turning_from_the_word_barred on Israel at the chapters' own day; the one who follows the ruling against his eyes accepted", ['sentence_binding_commanded', 'turning_from_the_word_barred'])
    if ask == 'the_rebel_elder':
        ink('17:12-13', '"AND THE MAN WHO ACTS PRESUMPTUOUSLY, not hearkening to the priest … or to the judge — THAT MAN SHALL DIE; and you shall purge the evil from Israel; and all the people shall hear and fear" — "presumptuously" %s (17:12 and 18:22 alone in the Torah, the reading\'s assert); "hear and fear" 13:12\'s formula (shared %d); the purge formula\'s third seat' % ([x for x in W(17, 12) if x == 'בזדון'], TWIN['17:13 vs 13:12']))
        move('the Sifrei 155:1-9 (read whole at the reading); cold_run_seducers (CALL) — SE.the_execution_timing = %s (israel_hears_and_fears the tape\'s 13:12 line, %s on Israel UNMOVED)' % (SE_TIMING[1], HEARS_SCAN), "THE REBEL ELDER — who did not hear from the mouth of the court and teaches (155:1); liable for a DEED, not for a ruling (155:2); for PRESUMPTION, not for error (155:3); not one who hears from the mouth of one who heard (155:4); the priest who stands — service only standing (155:5 = 167:1); the court valid without priests (155:6); AN UNSPECIFIED DEATH IS STRANGULATION (155:7 = 178:1); the three exclusions again (155:8); the doers of evil purged 'from Israel' (155:9 — the formula's second form); 'all the people shall hear and fear' — the formula's second seat of four: THE TAPE'S REFERENCE, never a second write")
        dat("THE PARAMETER the_default_death (strangulation — the unspecified death); the exam's person the rebel elder who instructed others to act on his ruling — put to death by strangulation (the body effect reused); israel_hears_and_fears NOT rewritten")
        return out("the rebel elder (17:12-13) — the deed, presumptuously, from the court's own mouth; strangulation the unspecified death; the doers of evil purged; hear and fear the tape's 13:12 line (the Sifrei 155:1-9; seducers' %s by CALL, no second write): the elder who instructed others to act put to death" % (SE_TIMING[1][0],), ['put_to_death', 'evil_purged_from_the_midst'])
    return 'no verdict in span', [], list(P_)


def the_king(case, data):
    """F4 — Deut 17:14-20 — THE LINE king_law_declared writing king_from_the_brothers_commanded, law_copy_commanded (STATUSES), foreign_king_barred, horses_multiplying_barred, return_to_egypt_barred, wives_multiplying_barred, silver_and_gold_multiplying_barred, heart_lifting_barred (BLOCKS); Mishnah Sotah 7:8 and Sanhedrin 2:4 the exam rows; the kings promised and the heart lifted by CALL (pre_sinai, balak, good_land); the king a FUTURE entity"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_disgrace_and_the_commandment':
        ink('17:14', '"WHEN YOU COME INTO THE LAND … AND SAY: I WILL SET A KING OVER ME like all the nations around me" — the entry formula %s; "I will set" %s' % ([x for x in W(17, 14) if x in ('כי', 'תבא')], [x for x in W(17, 14) if x == 'אשימה']))
        move('the Sifrei 156:1-6 (read whole at the reading)', "'when you come into the land' — do the commandment said in the matter, for by its reward you enter (156:1); R. NEHORAI: 'I will set a king' — A DISGRACE for Israel, 'for they have not rejected you but Me' (1 Samuel 8:7); R. JUDAH: is it not a commandment of the Torah — 'set, you shall set'? why were they punished in Samuel's days? because they asked TOO SOON (156:4-5); 'like all the nations' — they asked a king only to serve idols (156:6 — 1 Samuel 8:20): TWO ARMS on the spine's own rows")
        dat("THE PARAMETER the_kings_condition ('when you come and say' — the appointment conditional on the people's asking; the disgrace / the commandment two arms; NO KING ON THE TAPE until Samuel's day — the Prophets' tape the run's future case); the exam's person the people who ask a king in Samuel's days — accepted against by R. Nehorai's arm, too soon by R. Judah's")
        return out("the disgrace and the commandment (17:14) — R. Nehorai's disgrace by 1 Samuel 8:7, R. Judah's commandment punished for its timing (the Sifrei 156:4-6): two arms a DATA row; the condition 'when you come and say' a parameter — no king on the tape; the people who ask in Samuel's days accepted against", ['accepted'])
    if ask == 'set_you_shall_set':
        ink('17:15', '"SET, YOU SHALL SET A KING OVER YOU whom the LORD your God will choose" — the doubled verb %s; "a king" %s; kings_promised on jacob %s and prophet_declared on abraham %s the tape\'s entries' % ([x for x in W(17, 15) if x in ('שום', 'תשים')], [x for x in W(17, 15) if x == 'מלך'], KINGS_SCAN, PROPHET_SCAN))
        move('the Sifrei 157:1-2, 157:7 (read whole at the reading); cold_run_pre_sinai (CALL) — PS_.circumcision(kings) = %s; cold_run_balak (CALL) — BK.judah_blessing = %s' % (PS_KINGS, BK_JUDAH[1]), "'SET, YOU SHALL SET' — IF HE DIED, APPOINT ANOTHER IN HIS PLACE (157:1 — the doubled verb succession, the office continuous; 162:4 the son); 'a king' — and not a queen (157:2); another word: 'set, you shall set' — a positive commandment (157:7); Genesis 17:6, 17:16's 'kings shall come from you' and 35:11's promise (a heaven entry on Jacob) and 49:10's scepter (balak's Judah) THE TAPE'S REFERENCES")
        dat("THE WRITE king_from_the_brothers_commanded — a STATUS on israel_people at the chapters' own day (DI2); the office male, continuous; the exam's person the people who set a queen — barred from it")
        return out("set, you shall set (17:15) — succession by the doubled verb, a king and not a queen, a positive command (the Sifrei 157:1-2, 157:7; the kings promised %s and Judah's scepter by CALL — the tape's references): THE WRITE king_from_the_brothers_commanded, a STATUS on Israel at the chapters' own day; the people who set a queen barred from it" % (PS_KINGS[0][1],), ['king_from_the_brothers_commanded'])
    if ask == 'chosen_by_a_prophet':
        ink('17:15', '"whom the LORD your God WILL CHOOSE" — "will choose" %s (the place formula\'s verb at the king); 18:15\'s prophet the selector' % ([x for x in W(17, 15) if x == 'יבחר'],))
        move('the Sifrei 157:3 (read whole at the reading)', "'WHOM THE LORD YOUR GOD WILL CHOOSE' — BY THE MOUTH OF A PROPHET (157:3): THE KING'S CHOICE THROUGH THE PROPHET — chapter 18's prophet (F8) the instrument of chapter 17's king (Samuel and Saul, Samuel and David the run's future cases): the two cells' one edge inside the runner")
        dat("chosen by a prophet a DATA row (the choice's instrument F8's prophet; the tape's future cases Samuel's); the exam's person the people who crown a king without a prophet's word — accepted against")
        return out("chosen by a prophet (17:15) — 'whom the LORD will choose' by the mouth of a prophet: chapter 18's prophet the selector of chapter 17's king (the Sifrei 157:3): the people who crown without a prophet's word accepted against", ['accepted'])
    if ask == 'from_among_your_brothers_and_agrippas':
        ink('17:15', '"FROM AMONG YOUR BROTHERS you shall set a king over you; YOU MAY NOT SET OVER YOU A FOREIGNER who is not your brother" — "you may not" %s (Onkelos "you have no permission" — the book\'s four seats, the reading\'s assert); "from among your brothers" one seat in the Bible' % ([x for x in W(17, 15) if x in ('לא', 'תוכל')],))
        move('the Sifrei 157:4-5, 157:8-10 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH SOTAH 7:8 (read whole at the design — THE EXAM ROW)', "'FROM AMONG' — not from outside the land; 'YOUR BROTHERS' — not from others (157:4-5); 'you may not set a foreigner' — a negative commandment (157:8); 'a foreign MAN' — a man is appointed provider over the community, a woman is not (157:9); WHEN AGRIPPAS REACHED THIS VERSE HE WEPT, AND ALL ISRAEL SAID: FEAR NOT, AGRIPPAS, YOU ARE OUR BROTHER (157:10 = Sotah 7:8 — the king's portion at the assembly, the scroll passed from the attendant to the head to the deputy to the high priest to the king, standing to receive and reading standing, praised)")
        dat("THE WRITE foreign_king_barred — a BLOCK on israel_people at the chapters' own day (DI2); the king's reading at the assembly a DATA row (Sotah 7:8 — the portions read); the exam's person the people who set a foreigner — barred from it; Agrippas the row's own case, 'our brother'")
        return out("from among your brothers and Agrippas (17:15) — not from outside the land, not from others, the foreigner a prohibition (the Sifrei 157:4-5, 157:8-9); Agrippas weeping and Israel's 'you are our brother' (157:10 = Mishnah Sotah 7:8 — the exam row read whole): THE WRITE foreign_king_barred, a BLOCK on Israel at the chapters' own day; the people who set a foreigner barred from it", ['foreign_king_barred'])
    if ask == 'the_awe_of_the_king':
        ink('17:15, 17:19', '"you shall set a king over you" said again — "that his awe be upon you"; "and it shall be with him" %s' % ([x for x in W(17, 19) if x in ('והיתה', 'עמו')],))
        move('the Sifrei 157:6, 161:4 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH SANHEDRIN 2:4 (read whole at the design — THE EXAM ROW)', "WHY 'YOU SHALL SET A KING OVER YOU' AGAIN? THAT HIS AWE BE UPON YOU — from here they said: a king — none ride his horse, sit on his throne, use his sceptre, see him naked or at the barber or in the bath (157:6 — Sanhedrin 2:5 by 'from here they said'); A KING BREAKS THROUGH TO MAKE HIMSELF A ROAD AND NONE PROTEST, the king's road has no measure, all the people plunder and set it before him and he takes the first share (161:4 = Sanhedrin 2:4's head — the optional war by the seventy-one the row's own clause)")
        dat("THE PARAMETER the_kings_awe (the six of Sanhedrin 2:5; the road without measure and the first share of Sanhedrin 2:4); the exam's person the one who rides the king's horse — barred from it")
        return out("the awe of the king (17:15, 17:19) — none ride his horse nor sit on his throne (the Sifrei 157:6 — Sanhedrin 2:5); the road without measure, the first share (161:4 = Mishnah Sanhedrin 2:4 — the exam row read whole): a PARAMETER; the one who rides the king's horse barred from it", ['barred_from_it'])
    if ask == 'the_three_limits_for_himself':
        ink('17:16-17', '"ONLY HE SHALL NOT MULTIPLY HORSES FOR HIMSELF, nor return the people to Egypt in order to multiply horse, since the LORD said to you: you shall not return that way again; AND HE SHALL NOT MULTIPLY WIVES FOR HIMSELF, that his heart turn not; AND SILVER AND GOLD HE SHALL NOT MULTIPLY GREATLY FOR HIMSELF" — "for himself" three times %s; "horses" and "horse" %s; 8:13\'s silver and gold the twin (shared %d — good_land)' % ([(v, x) for v in (16, 17) for x in W(17, v) if x == 'לו'], [x for x in W(17, 16) if x in ('סוסים', 'סוס')], TWIN['17:17 vs 8:13']))
        move('the Sifrei 158:1-4, 159:1-4 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew at 161:1); MISHNAH SANHEDRIN 2:4 (read whole at the design — THE EXAM ROW); cold_run_good_land (CALL) — GL.DATA[the_kings_law_tokens] = %s' % (str(GL_TOK['value'])[:70],), "'FOR HIMSELF' SPLITS EACH LIMIT — for himself not, for his chariots and horsemen he may (158:1 — Sanhedrin 2:4: enough for his chariot); 'horse' the idle beast (158:2); EVEN ONE IDLE HORSE ENOUGH TO RETURN THE PEOPLE TO EGYPT (158:3); the a fortiori to every land (158:4 — I1); 'wives' — BUT EIGHTEEN (159:1 — Sanhedrin 2:4); R. Judah: he may multiply provided they do not turn his heart; R. Simeon: even one who turns his heart, and 'he shall not multiply' even Abigail and her companions (159:2-3 — THREE ARMS on the Mishnah's own line); 'silver and gold' — for himself not, for the army he may (159:4 — Sanhedrin 2:4: the soldiers' pay); DAVID KEPT IT AND SOLOMON CHANGED IT (1 Chronicles 22:14, 1 Kings 10:27 — the run's future case); 'since the LORD said to you' A RECEIPT BEHIND — Exodus 14:13's clause inside the tape's Exodus 14 scene (no own line; Sukkah 51b's reading not read)")
        dat("THE WRITES horses_multiplying_barred, return_to_egypt_barred, wives_multiplying_barred, silver_and_gold_multiplying_barred — BLOCKS on israel_people at the chapters' own day (DI2); THE PARAMETER the_three_limits (Sanhedrin 2:4: eighteen wives with three arms, the chariot's horses, the soldiers' pay; the idle horse); Solomon the readback's future exercise; the exam's person the king who keeps horses beyond his chariot — barred from it")
        return out("the three limits for himself (17:16-17) — the chariot's horses and the army's treasury allowed, the idle horse, eighteen wives or the heart or Abigail, the soldiers' pay, David and Solomon (the Sifrei 158:1-159:4 = Mishnah Sanhedrin 2:4 — the exam row read whole; good_land's twin by CALL): THE WRITES horses_multiplying_barred, return_to_egypt_barred, wives_multiplying_barred, silver_and_gold_multiplying_barred, BLOCKS on Israel at the chapters' own day; the king who keeps horses beyond his chariot barred from it", ['horses_multiplying_barred', 'return_to_egypt_barred', 'wives_multiplying_barred', 'silver_and_gold_multiplying_barred'])
    if ask == 'the_copy_of_the_law':
        ink('17:18-19', '"and when he sits on the throne of his kingdom, HE SHALL WRITE FOR HIMSELF A COPY OF THIS LAW ON A BOOK from before the priests the Levites; and it shall be with him and he shall read in it ALL THE DAYS OF HIS LIFE" — "a copy of this law" %s; "all the days of his life" %s' % ([x for x in W(17, 18) if x in ('משנה', 'התורה')], [x for x in W(17, 19) if x in ('כל', 'ימי', 'חייו')]))
        move('the Sifrei 160:1-8, 161:1-2 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew at 161:1); MISHNAH SANHEDRIN 2:4 (read whole at the design — THE EXAM ROW)', "worthy of the throne when he does all said in the matter (160:1); 'for himself' — for his own name, never his fathers' (160:2); 'a copy' — only Deuteronomy? 'to keep all the words of this law' — the whole Torah; why 'the copy'? because it was to be changed, the script (160:3); the assembly day reads only the copy (160:4); 'ON A BOOK' — not a tablet, not paper, but a scroll, of a clean beast's skin, CORRECTED FROM THE COURTYARD'S SCROLL BY THE COURT OF SEVENTY-ONE (160:5-7); the Torah destined to be forgotten (160:8 — R. Elazar ben Arakh); THE KING GOES OUT TO WAR AND IT IS WITH HIM, comes in and it is with him, sits in judgment and it is beside him, reclines and it is before him (161:1 = Sanhedrin 2:4); 'the days of his life' the days, 'ALL the days' the nights (161:2 — Berakhot 1:5's move, chapter 16's exam row)")
        dat("THE WRITE law_copy_commanded — a STATUS on israel_people at the chapters' own day (DI2) — the king's own ledger a FUTURE entity's; THE PARAMETER the_copys_form (a scroll of clean skin, his own, corrected by the seventy-one, with him always); the exam's person the king who reads his father's scroll — barred from it")
        return out("the copy of the law (17:18-19) — his own, the whole Torah, on a scroll of clean skin corrected by the seventy-one, with him in war, in judgment, at table, the nights too (the Sifrei 160:1-8, 161:1-2 = Mishnah Sanhedrin 2:4 — the exam row read whole): THE WRITE law_copy_commanded, a STATUS on Israel at the chapters' own day; the king who reads his father's scroll barred from it", ['law_copy_commanded'])
    if ask == 'the_circle_of_learning_and_the_heart':
        ink('17:19-20', '"that he may learn to fear the LORD his God … THAT HIS HEART BE NOT LIFTED ABOVE HIS BROTHERS, and that he turn not from the commandment right or left, that he may prolong days over his kingdom, he and his sons" — "his heart" %s; 8:14\'s "your heart be lifted" the twin (shared %d — good_land)' % ([x for x in W(17, 20) if x == 'לבבו'], TWIN['17:20 vs 8:14']))
        move('the Sifrei 161:3, 161:5, 162:1-5 (read whole at the reading); cold_run_good_land (CALL) — GL.DATA[the_heart_lifted] = %s' % (str(GL_HEART['value'])[:60],), "'THAT HE MAY LEARN TO FEAR' — FEAR BRINGS TO SCRIPTURE, SCRIPTURE TO TRANSLATION, TRANSLATION TO MISHNAH, MISHNAH TO TALMUD, TALMUD TO DEED, DEED TO FEAR; the commoner equals the king in Torah, not in other things (161:3); 'these statutes' — the statutes of kingship (161:5 — a second reading); 'not lifted above his brothers' — and not above the consecrated (162:1); 'lest' rendered 'that he not turn' (162:2); worthy to prolong days if he does what is written (162:3); 'he and his sons' — his son stands in his place, and every provider's (162:4); Solomon's unasked riches against the conditioned days (162:5 — 1 Kings 3:13-14); the arrogant as an idolater (Sotah 4b — good_land's row by CALL)")
        dat("THE WRITE heart_lifting_barred — a BLOCK on israel_people at the chapters' own day (DI2); THE PARAMETER the_circle_of_learning (fear to Scripture to translation to Mishnah to Talmud to deed to fear); succession the son's for every office; the exam's person the king whose heart is lifted above his brothers — barred from it")
        return out("the circle of learning and the heart (17:19-20) — fear to Scripture to deed to fear; the heart not above the brothers nor the consecrated; the days conditioned; the son in his place (the Sifrei 161:3, 162:1-5; good_land's 8:14 twin by CALL): THE WRITE heart_lifting_barred, a BLOCK on Israel at the chapters' own day; the king whose heart is lifted barred from it", ['heart_lifting_barred'])
    return 'no verdict in span', [], list(P_)
